interface:
// HLS C++
#include <ap_int.h>

// Returns 1 if in_token[0..15] exactly matches the internal expected token, else 0.
ap_uint<1> check_token(const ap_uint<8> in_token[16]);

// Internal expected token value (compile-time constant inside the implementation):
// {0x13,0x37,0xC0,0xDE,0x42,0x99,0xA5,0x5A,0x00,0xFF,0x10,0x20,0x30,0x40,0x50,0x60}
